import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-GET-Command.md","filePath":"manual-en/Matrix-GET-Command.md","lastUpdated":1785684581000}'),n={name:"manual-en/Matrix-GET-Command.md"};function s(d,e,r,c,m,l){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h4 id="_16-4-9-the-get-command" tabindex="-1">16.4.9 The <code>GET</code> Command <a class="header-anchor" href="#_16-4-9-the-get-command" aria-label="Permalink to &quot;16.4.9 The \`GET\` Command&quot;">​</a></h4><pre><code>GET _variable_[(_index_[,_index_])]
    [/FILE={_file_ _|_ *}]
    [/VARIABLES=_variable_ …]
    [/NAMES=_variable_]
    [/MISSING={ACCEPT _|_ OMIT _|_ _number_}]
    [/SYSMIS={OMIT _|_ _number_}].
</code></pre><p>The <code>READ</code> command reads numeric data from an SPSS system file, SPSS/PC+ system file, or SPSS portable file into a matrix variable or submatrix:</p><ul><li>To read data into a variable, specify just its name following <code>GET</code>. The variable need not already exist; if it does, it is replaced. The variable will have as many columns as there are variables specified on the <code>VARIABLES</code> subcommand and as many rows as there are cases in the input file.</li><li>To read data into a submatrix, specify the name of an existing variable, followed by an indexing expression, just after <code>GET</code>. The submatrix must have as many columns as variables specified on <code>VARIABLES</code> and as many rows as cases in the input file.</li></ul><p>Specify the name or handle of the file to be read on <code>FILE</code>. Use ‘*’, or simply omit the <code>FILE</code> subcommand, to read from the active file. Reading from the active file is only permitted if it was already defined outside <code>MATRIX</code>.</p><p>List the variables to be read as columns in the matrix on the <code>VARIABLES</code> subcommand. The list can use <code>TO</code> for collections of variables or <code>ALL</code> for all variables. If <code>VARIABLES</code> is omitted, all variables are read. Only numeric variables may be read.</p><p>If a variable is named on <code>NAMES</code>, then the names of the variables read as data columns are stored in a string vector within the given name, replacing any existing matrix variable with that name. Variable names are truncated to 8 bytes.</p><p>The <code>MISSING</code> and <code>SYSMIS</code> subcommands control the treatment of missing values in the input file. By default, any user- or system-missing data in the variables being read from the input causes an error that prevents <code>GET</code> from executing. To accept missing values, specify one of the following settings on <code>MISSING</code>:</p><p><code>ACCEPT</code></p><p>Accept user-missing values with no change.</p><p>By default, system-missing values still yield an error. Use the <code>SYSMIS</code> subcommand to change this treatment:</p><p><code>OMIT</code></p><p>Skip any case that contains a system-missing value.</p><p><em>number</em></p><p>Recode the system-missing value to <em>number</em>.</p><p><code>OMIT</code></p><p>Skip any case that contains any user- or system-missing value.</p><p><em>number</em></p><p>Recode all user- and system-missing values to <em>number</em>.</p><p>The <code>SYSMIS</code> subcommand has an effect only with <code>MISSING=ACCEPT</code>.</p>`,20)])])}const h=a(n,[["render",s]]);export{u as __pageData,h as default};
